package com.mamtrex.hospital.appointment;
import com.mamtrex.hospital.organization.Branch; import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="appointments") public class Appointment extends BaseEntity { private String patientId; private String professionalId; private String scheduledAt; private String type; private String status; /* Branch ownership (docs/plan3.md Task 4): workflow creates derive it from the acting context, never client input; null is the deliberate legacy seam for pre-Task-4 rows, which stay invisible through branch-scoped endpoints. The String-typed reference columns stay the established legacy persistence representation. */ @ManyToOne @JoinColumn(name="branch_id") private Branch branch; protected Appointment(){} public Appointment(Branch branch, String patientId, String professionalId, String scheduledAt, String type, String status){this.branch=branch; this.patientId=patientId; this.professionalId=professionalId; this.scheduledAt=scheduledAt; this.type=type; this.status=status;} public String getPatientId(){return patientId;} public String getProfessionalId(){return professionalId;} public String getScheduledAt(){return scheduledAt;} public String getType(){return type;} public String getStatus(){return status;} public Branch getBranch(){return branch;} }
